inline const Info* FindByName(const char* name) {
    if (!name) return nullptr;
    for (int i = 0; i < kCount; ++i)
        if (strcmp(kTypes[i].name, name) == 0) return &kTypes[i];
    return nullptr;
}

inline const Info* FindByFactoryVTable(uint32_t rva) {
    if (!rva) return nullptr;
    for (int i = 0; i < kCount; ++i)
        if (kTypes[i].factoryVtRVA == rva) return &kTypes[i];
    return nullptr;
}

inline const Info* FindByTypeId(uint16_t id) {
    if (!id) return nullptr;
    for (int i = 0; i < kCount; ++i)
        if (kTypes[i].typeId == id) return &kTypes[i];
    return nullptr;
}

